  // ===== EXPORT PDF (FULLY WORKING) =====
  const exportPDF = () => {
    if (leads.length === 0) {
      toast.error('No leads to export');
      return;
    }

    try {
      const doc = new jsPDF();
      let y = 20;

      // ===== HEADER =====
      doc.setFillColor(124, 58, 237);
      doc.rect(0, 0, 210, 35, 'F');
      doc.setFontSize(20);
      doc.setTextColor(255, 255, 255);
      doc.text('📊 LeadHunter Report', 105, 18, { align: 'center' });
      doc.setFontSize(9);
      doc.setTextColor(200, 200, 220);
      doc.text(new Date().toLocaleString(), 105, 28, { align: 'center' });

      y = 45;

      // ===== SUMMARY STATS =====
      const total = leads.length;
      const saved = leads.filter(l => l.isSaved).length;
      const countries = [...new Set(leads.map(l => l.country).filter(Boolean))].length;
      const industries = [...new Set(leads.map(l => l.industry).filter(Boolean))].length;

      doc.setFontSize(11);
      doc.setTextColor(50, 50, 50);
      doc.text(`📌 Total Leads: ${total}  |  ⭐ Saved: ${saved}  |  🌍 Countries: ${countries}  |  🏢 Industries: ${industries}`, 14, y);
      y += 12;

      // ===== TABLE =====
      const tableColumn = ["#", "Company", "Industry", "City", "Country", "Phone", "Email", "Status"];
      const tableRows = [];

      leads.forEach((lead, index) => {
        const leadData = [
          (index + 1).toString(),
          (lead.companyName || 'N/A').substring(0, 25),
          (lead.industry || 'N/A').substring(0, 15),
          (lead.city || 'N/A').substring(0, 15),
          (lead.country || 'N/A').substring(0, 12),
          lead.phone || 'N/A',
          (lead.email || 'N/A').substring(0, 20),
          lead.status || 'New'
        ];
        tableRows.push(leadData);
      });

      doc.autoTable({
        startY: y,
        head: [tableColumn],
        body: tableRows,
        theme: 'striped',
        headStyles: {
          fillColor: [124, 58, 237],
          textColor: [255, 255, 255],
          fontSize: 9,
          fontStyle: 'bold'
        },
        bodyStyles: {
          fontSize: 8
        },
        columnStyles: {
          0: { cellWidth: 10, halign: 'center' },
          1: { cellWidth: 45 },
          2: { cellWidth: 25 },
          3: { cellWidth: 22 },
          4: { cellWidth: 18 },
          5: { cellWidth: 25 },
          6: { cellWidth: 32 },
          7: { cellWidth: 18, halign: 'center' }
        },
        didDrawPage: function(data) {
          const pageCount = doc.internal.getNumberOfPages();
          doc.setFontSize(7);
          doc.setTextColor(150, 150, 150);
          doc.text(`Page ${data.pageNumber} of ${pageCount}`, 190, 285);
          doc.text('LeadHunter Pro - Lead Generation Platform', 14, 285);
        }
      });

      // ===== SAVE =====
      const fileName = `leads_report_${new Date().toISOString().slice(0,10)}.pdf`;
      doc.save(fileName);
      toast.success(`✅ ${leads.length} leads exported to PDF!`);

    } catch (error) {
      console.error('PDF Error:', error);
      toast.error('Failed to generate PDF. Please try again.');
    }
  };

  // ===== ANALYTICS DATA =====
  const getAnalyticsData = () => {
    const countryMap = {};
    leads.forEach(lead => {
      const country = lead.country || 'Unknown';
      countryMap[country] = (countryMap[country] || 0) + 1;
    });
    const countryData = Object.entries(countryMap)
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    const industryMap = {};
    leads.forEach(lead => {
      const industry = lead.industry || 'Unknown';
      industryMap[industry] = (industryMap[industry] || 0) + 1;
    });
    const industryData = Object.entries(industryMap)
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    const statusMap = {};
    leads.forEach(lead => {
      const status = lead.status || 'Unknown';
      statusMap[status] = (statusMap[status] || 0) + 1;
    });
    const statusData = Object.entries(statusMap)
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    const totalLeads = leads.length;
    const savedLeads = leads.filter(l => l.isSaved).length;

    return { countryData, industryData, statusData, totalLeads, savedLeads };
  };

